<script setup lang="ts">
import {ref,watch} from 'vue'
type Fields={email:string;phone:string;whatsapp:string;address:string;instagram:string}
const props=defineProps<{id:string;data?:Partial<Fields>|null;status?:string;message?:string;evidence?:string|null;approved:boolean}>(),emit=defineEmits<{saved:[]}>()
const text=ref(props.evidence||''),busy=ref(false),error=ref(''),notice=ref('')
const fields=ref<Fields>({email:'',phone:'',whatsapp:'',address:'',instagram:''})
watch(()=>props.data,d=>{fields.value={email:d?.email||'',phone:d?.phone||'',whatsapp:d?.whatsapp||'',address:d?.address||'',instagram:d?.instagram||''}},{immediate:true,deep:true})
async function act(action:string){busy.value=true;error.value='';notice.value='';try{const r=await fetch(`/api/discovery/leads/${props.id}/${action}`,{method:action==='contact'?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(action==='extract'?{text:text.value}:action==='contact'?fields.value:{})});const d=await r.json();if(!r.ok)throw new Error(d.error||'读取失败');notice.value=action==='contact'?'联系方式已核对保存，可审核入库':'已提取候选信息，请核对下方字段后保存';emit('saved')}catch(e){error.value=e instanceof Error?e.message:'请求失败';emit('saved')}finally{busy.value=false}}
</script>
<template><section class="contacts-editor"><h2>店铺公开联系资料</h2><p>{{message||'尚未读取主页公开资料。可以尝试直接读取；如平台要求登录，请打开原始主页复制公开简介。'}}</p><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><template v-if="!approved"><button :disabled="busy" @click="act('enrich')">{{busy?'处理中…':'读取公开主页联系信息'}}</button><details class="spaced"><summary>粘贴主页简介 / 联系资料进行提取</summary><textarea v-model="text" rows="5" maxlength="30000" placeholder="粘贴店铺公开简介中的邮箱、电话、WhatsApp 等资料" aria-label="公开联系资料原文"></textarea><button :disabled="busy||!text.trim()" @click="act('extract')">提取邮箱与电话</button></details></template><div class="contact-fields"><label v-for="(label,key) in {email:'商务邮箱',phone:'电话（国际号码）',whatsapp:'WhatsApp（国际号码）',address:'店铺地址',instagram:'Instagram 账号'}">{{label}}<input v-model="fields[key]" :readonly="approved" :type="key==='email'?'email':'text'" :placeholder="key==='phone'||key==='whatsapp'?'+234…':''"/></label></div><button v-if="!approved" class="primary" :disabled="busy" @click="act('contact')">核对并保存联系方式</button><p>只有页面明确标注为 WhatsApp 的号码才填写 WhatsApp；电话号码不会自动认定为 WhatsApp。未找到的字段保留为空。</p><details v-if="evidence"><summary>查看已保存的联系资料原文</summary><p class="raw">{{evidence}}</p></details></section></template>
<style scoped>.contacts-editor{padding:18px;background:#fff;border:1px solid #e0e8e3;border-radius:5px;margin:16px 0}.contact-fields{display:grid;grid-template-columns:1fr 1fr;gap:0 15px}.error{background:#fbe8ee;color:#963c55;padding:10px}.raw{max-height:200px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:700px){.contact-fields{grid-template-columns:1fr}}</style>
